// 10 000 objects, each with its own Update: 10 000 calls a frame
public class Bob : MonoBehaviour
{
    public float phase;
    void Update()
    {
        var p = transform.localPosition;
        p.y = Mathf.Sin(Time.time + phase);   // main-thread API, one by one
        transform.localPosition = p;
    }
}

// inside a job none of this is allowed:
// transform, GameObject, GetComponent, Physics.Raycast, Time.time

using UnityEngine.Jobs;

[BurstCompile]
struct BobJob : IJobParallelForTransform
{
    [ReadOnly] public NativeArray<float> phase;
    public float time;                       // Time.time, passed in as a field

    public void Execute(int i, TransformAccess t)
    {
        var p = t.localPosition;
        p.y = math.sin(time + phase[i]);
        t.localPosition = p;
    }
}

TransformAccessArray transforms;   // Awake: new TransformAccessArray(bobTransforms)
JobHandle handle;

void Update()
{
    handle = new BobJob { phase = phase, time = Time.time }.Schedule(transforms);
    JobHandle.ScheduleBatchedJobs();
}
void LateUpdate() => handle.Complete();
void OnDestroy() { handle.Complete(); transforms.Dispose(); phase.Dispose(); }

// Scene A: one parent, 10 000 children
//   Enemies
//     Enemy_0 ... Enemy_9999   -> one shared root: Schedule uses ONE thread
//
// Scene B: 10 000 objects at the scene root
//   Enemy_0 ... Enemy_9999     -> different roots: spread over the workers

// gather positions in parallel whatever the hierarchy
[BurstCompile]
struct GatherJob : IJobParallelForTransform
{
    [WriteOnly] public NativeArray<float3> positions;
    public void Execute(int i, TransformAccess t)
    {
        if (t.isValid) positions[i] = t.position;
    }
}
handle = new GatherJob { positions = positions }.ScheduleReadOnly(transforms, 64);

int n = 500;
var commands = new NativeArray<RaycastCommand>(n, Allocator.TempJob);
var results  = new NativeArray<RaycastHit>(n * maxHits, Allocator.TempJob);

var query = new QueryParameters(groundMask);   // layerMask, triggers, back faces
for (int i = 0; i < n; i++)
    commands[i] = new RaycastCommand(agents[i].position, Vector3.down, query, 10f);

// the rays run in jobs, in parallel with each other
JobHandle h = RaycastCommand.ScheduleBatch(commands, results, 32, maxHits);
// ... other main-thread work ...
h.Complete();          // results are off-limits until here

h.Complete();
for (int i = 0; i < n; i++)
{
    for (int k = 0; k < maxHits; k++)
    {
        RaycastHit hit = results[i * maxHits + k];  // command i starts at i * maxHits
        if (hit.collider == null) break;            // first empty slot: stop
        OnHit(i, hit.point, hit.normal);
    }
}
commands.Dispose();
results.Dispose();

// chain: a Burst job fills the commands, the batch depends on it
JobHandle fill = new FillRaysJob { origins = origins, commands = commands }.Schedule(n, 64);
JobHandle cast = RaycastCommand.ScheduleBatch(commands, results, 32, 1, fill);

