using Unity.Collections;
using Unity.Jobs;
using UnityEngine;

public class GroundProbe : MonoBehaviour
{
    public Transform[] agents;          // 500 agents
    public LayerMask groundMask;
    float[] groundY;

    NativeArray<RaycastCommand> commands;
    NativeArray<RaycastHit> results;
    JobHandle handle;

    void Awake()
    {
        commands = new NativeArray<RaycastCommand>(agents.Length, Allocator.Persistent);
        results = new NativeArray<RaycastHit>(agents.Length, Allocator.Persistent);
        groundY = new float[agents.Length];
    }

    void Update()
    {
        var query = new QueryParameters(groundMask);
        for (int i = 0; i < agents.Length; i++)
            commands[i] = new RaycastCommand(agents[i].position, Vector3.down, query, 10f);
        handle = RaycastCommand.ScheduleBatch(commands, results, 32, 1);
        JobHandle.ScheduleBatchedJobs();
    }

    void LateUpdate()
    {
        handle.Complete();
        for (int i = 0; i < agents.Length; i++)
            if (results[i].collider != null)        // maxHits = 1: one slot per ray
                groundY[i] = results[i].point.y;
    }

    void OnDestroy()
    {
        handle.Complete();                      // the batch may still write to results
        commands.Dispose();
        results.Dispose();
    }
}
